const listEinvoices = `-- name: ListEinvoices :many
SELECT e.id, e.uuid, e.organization_id, e.brand_id, e.number, e.profile, e.invoice_type, e.source_type, e.source_uuid, e.buyer_org_id, e.buyer, e.seller, e.lines, e.currency, e.rate_snapshot, e.line_extension, e.tax_exclusive, e.tax_total, e.payable, e.tax_breakdown, e.xml_storage_key, e.xml_sha256, e.pdf_storage_key, e.validation_status, e.validation_messages, e.status, e.error, e.voided_at, e.voided_by, e.void_reason, e.issue_date, e.created_by, e.created_at, e.updated_at, bo.uuid AS buyer_org_uuid, bo.name AS buyer_org_name,
       COUNT(*) OVER()::bigint AS total_count
FROM einvoices e
LEFT JOIN organizations bo ON bo.id = e.buyer_org_id
WHERE e.brand_id = $1
  AND ($2::bigint[] IS NULL OR e.organization_id = ANY ($2::bigint[]))
  AND (COALESCE(cardinality($3::text[]), 0) = 0 OR e.status = ANY ($3::text[]))
  AND (COALESCE(cardinality($4::text[]), 0) = 0 OR e.profile = ANY ($4::text[]))
  AND (COALESCE(cardinality($5::bigint[]), 0) = 0 OR e.buyer_org_id = ANY ($5::bigint[]))
  AND ($6::date IS NULL OR e.issue_date >= $6::date)
  AND ($7::date IS NULL OR e.issue_date <= $7::date)
  AND ($8::numeric IS NULL OR e.payable >= $8::numeric)
  AND ($9::numeric IS NULL OR e.payable <= $9::numeric)
  AND (
    $10::text IS NULL
    OR e.number ILIKE '%' || $10::text || '%'
    OR e.uuid::text ILIKE '%' || $10::text || '%'
    OR bo.name ILIKE '%' || $10::text || '%'
    OR e.buyer ->> 'legal_name' ILIKE '%' || $10::text || '%'
    OR e.buyer ->> 'name' ILIKE '%' || $10::text || '%'
  )
ORDER BY
  CASE WHEN NOT $11::bool AND $12::text = 'issue_date' THEN e.issue_date END ASC,
  CASE WHEN $11::bool AND $12::text = 'issue_date' THEN e.issue_date END DESC,
  CASE WHEN NOT $11::bool THEN
    CASE $12::text WHEN 'number' THEN e.number WHEN 'status' THEN e.status END
  END ASC,
  CASE WHEN $11::bool THEN
    CASE $12::text WHEN 'number' THEN e.number WHEN 'status' THEN e.status END
  END DESC,
  CASE WHEN NOT $11::bool AND $12::text = 'payable' THEN e.payable END ASC,
  CASE WHEN $11::bool AND $12::text = 'payable' THEN e.payable END DESC,
  CASE WHEN NOT $11::bool AND $12::text = 'created_at' THEN e.created_at END ASC,
  CASE WHEN $11::bool AND $12::text = 'created_at' THEN e.created_at END DESC,
  CASE WHEN $11::bool THEN e.id END DESC,
  e.id ASC
LIMIT $14 OFFSET $13
`

