// List contract: sort=issue_date|number|payable|status|created_at, default
// -issue_date; id is the stable tiebreak. q matches number, buyer legal/name
// fields and ETTN. status/profile/buyer_org_ids are multi-value filters.
func (q *Queries) ListEinvoices(ctx context.Context, arg ListEinvoicesParams) ([]ListEinvoicesRow, error) {
	rows, err := q.db.Query(ctx, listEinvoices,
		arg.BrandID,
		arg.OrgIds,
		arg.Statuses,
		arg.Profiles,
		arg.BuyerOrgIds,
		arg.IssueDateFrom,
		arg.IssueDateTo,
		arg.PayableMin,
		arg.PayableMax,
		arg.Q,
		arg.SortDesc,
		arg.SortKey,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListEinvoicesRow{}
	for rows.Next() {
		var i ListEinvoicesRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.BrandID,
			&i.Number,
			&i.Profile,
			&i.InvoiceType,
			&i.SourceType,
			&i.SourceUuid,
			&i.BuyerOrgID,
			&i.Buyer,
			&i.Seller,
			&i.Lines,
			&i.Currency,
			&i.RateSnapshot,
			&i.LineExtension,
			&i.TaxExclusive,
			&i.TaxTotal,
			&i.Payable,
			&i.TaxBreakdown,
			&i.XmlStorageKey,
			&i.XmlSha256,
			&i.PdfStorageKey,
			&i.ValidationStatus,
			&i.ValidationMessages,
			&i.Status,
			&i.Error,
			&i.VoidedAt,
			&i.VoidedBy,
			&i.VoidReason,
			&i.IssueDate,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.BuyerOrgUuid,
			&i.BuyerOrgName,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

